    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 79-year-old female named Catherine with moderate dementia has been cared for at home by her spouse for the past 3 years. The spouse reports feeling overwhelmed, missing work, and having no time for personal activities. The clinician administers the Zarit Burden Interview (ZBI), and the spouse scores 58. Which of the following is the most appropriate interpretation and next step?', '["A ZBI score \u2265 21 indicates significant caregiver burden; refer the caregiver to a social worker, recommend a caregiver support group, arrange respite care services, and screen the caregiver for depression and burnout", "The ZBI is used exclusively to assess the patient''s cognitive decline; repeat the Mini-Mental State Examination (MMSE) to evaluate the patient''s disease progression", "A ZBI score in this range mandates immediate involuntary psychiatric hospitalization of the caregiver for acute burnout syndrome", "A ZBI score of this level is within normal limits for caregivers; reassure the spouse that these feelings are completely expected and require no intervention", "Advise the caregiver that their only legal option is to continue providing full-time home care without institutional support until the patient dies"]'::jsonb, 0, 'The **Zarit Burden Interview (ZBI)** is a validated 22-item self-report tool used to assess caregiver burden in dementia caregivers. Scores range from 0–88, with higher scores indicating greater burden. Thresholds: 0–20 (little/no burden), 21–40 (mild–moderate), 41–60 (moderate–severe), 61–88 (severe burden). Any score ≥ 21 warrants clinical intervention. Interventions include: (1) referral to a licensed clinical social worker; (2) enrollment in caregiver support groups (e.g., Alzheimer''s Association); (3) arrangement of **respite care** (temporary relief: adult day programs, short-term nursing home stays); (4) depression and anxiety screening for the caregiver (PHQ-9, GAD-7); (5) community resource linkage. Caregiver health directly impacts patient outcomes. (Ref: Hazzard''s Ch. 14 & Ch. 17; AGS Geriatrics At Your Fingertips; UWorld Step 2 CK)'),
    (v_topic_id, 'A 95-year-old male named Harold with advanced dementia has been cared for at home by his spouse for the past 2 years. The spouse reports feeling overwhelmed, missing work, and having no time for personal activities. The clinician administers the Zarit Burden Interview (ZBI), and the spouse scores 48. Which of the following is the most appropriate interpretation and next step?', '["Advise the caregiver that their only legal option is to continue providing full-time home care without institutional support until the patient dies", "A ZBI score \u2265 21 indicates significant caregiver burden; refer the caregiver to a social worker, recommend a caregiver support group, arrange respite care services, and screen the caregiver for depression and burnout", "A ZBI score in this range mandates immediate involuntary psychiatric hospitalization of the caregiver for acute burnout syndrome", "The ZBI is used exclusively to assess the patient''s cognitive decline; repeat the Mini-Mental State Examination (MMSE) to evaluate the patient''s disease progression", "A ZBI score of this level is within normal limits for caregivers; reassure the spouse that these feelings are completely expected and require no intervention"]'::jsonb, 1, 'The **Zarit Burden Interview (ZBI)** is a validated 22-item self-report tool used to assess caregiver burden in dementia caregivers. Scores range from 0–88, with higher scores indicating greater burden. Thresholds: 0–20 (little/no burden), 21–40 (mild–moderate), 41–60 (moderate–severe), 61–88 (severe burden). Any score ≥ 21 warrants clinical intervention. Interventions include: (1) referral to a licensed clinical social worker; (2) enrollment in caregiver support groups (e.g., Alzheimer''s Association); (3) arrangement of **respite care** (temporary relief: adult day programs, short-term nursing home stays); (4) depression and anxiety screening for the caregiver (PHQ-9, GAD-7); (5) community resource linkage. Caregiver health directly impacts patient outcomes. (Ref: Hazzard''s Ch. 14 & Ch. 17; AGS Geriatrics At Your Fingertips; UWorld Step 2 CK)'),
    (v_topic_id, 'A 79-year-old female named Bernice with mild dementia has been cared for at home by her paid caregiver for the past 4 years. The paid caregiver reports feeling overwhelmed, missing work, and having no time for personal activities. The clinician administers the Zarit Burden Interview (ZBI), and the paid caregiver scores 58. Which of the following is the most appropriate interpretation and next step?', '["The ZBI is used exclusively to assess the patient''s cognitive decline; repeat the Mini-Mental State Examination (MMSE) to evaluate the patient''s disease progression", "A ZBI score of this level is within normal limits for caregivers; reassure the paid caregiver that these feelings are completely expected and require no intervention", "A ZBI score in this range mandates immediate involuntary psychiatric hospitalization of the caregiver for acute burnout syndrome", "Advise the caregiver that their only legal option is to continue providing full-time home care without institutional support until the patient dies", "A ZBI score \u2265 21 indicates significant caregiver burden; refer the caregiver to a social worker, recommend a caregiver support group, arrange respite care services, and screen the caregiver for depression and burnout"]'::jsonb, 4, 'The **Zarit Burden Interview (ZBI)** is a validated 22-item self-report tool used to assess caregiver burden in dementia caregivers. Scores range from 0–88, with higher scores indicating greater burden. Thresholds: 0–20 (little/no burden), 21–40 (mild–moderate), 41–60 (moderate–severe), 61–88 (severe burden). Any score ≥ 21 warrants clinical intervention. Interventions include: (1) referral to a licensed clinical social worker; (2) enrollment in caregiver support groups (e.g., Alzheimer''s Association); (3) arrangement of **respite care** (temporary relief: adult day programs, short-term nursing home stays); (4) depression and anxiety screening for the caregiver (PHQ-9, GAD-7); (5) community resource linkage. Caregiver health directly impacts patient outcomes. (Ref: Hazzard''s Ch. 14 & Ch. 17; AGS Geriatrics At Your Fingertips; UWorld Step 2 CK)'),
